package com.worksphere.service;
import com.worksphere.entity.*; import com.worksphere.repository.*; import com.worksphere.exception.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.util.*;
@Service public class UserService { private final UserRepository users; public UserService(UserRepository u){users=u;} public User current(Authentication a){return users.findByEmail(a.getName()).orElseThrow(()->new ResourceNotFoundException("User not found"));} public User byId(Long id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found"));} public List<User> all(){return users.findAllByOrderByCreatedAtDesc();} }
